static int *depth;
static int **up;
static ll *distRoot;

static void addEdge(int u, int v, ll w) {
    edges[edgeCnt].to = v;
    edges[edgeCnt].w = w;
    edges[edgeCnt].next = head[u];
    head[u] = edgeCnt++;
}

static int max_int(int a, int b) { return a > b ? a : b; }

static int lca(int a, int b) {
    if (depth[a] < depth[b]) {
        int t = a; a = b; b = t;
    }

    int diff = depth[a] - depth[b];
    for (int k = 0; k < LOGN; k++) {
        if (diff & (1 << k)) a = up[k][a];
    }

    if (a == b) return a;

    for (int k = LOGN - 1; k >= 0; k--) {
        if (up[k][a] != up[k][b]) {
            a = up[k][a];
            b = up[k][b];
        }
    }
    return up[0][a];
}

static ll dist(int a, int b) {
    int c = lca(a, b);
    return distRoot[a] + distRoot[b] - 2LL * distRoot[c];
}

