public class Main {
    static int N;
    static List<int[]>[] tree;
    static final int LOG = 17; // since N <= 100000, 2^17 = 131072
    static int[] depth;
    static int[][] parent;
    static long[] distFromRoot;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        N = Integer.parseInt(st.nextToken());
        tree = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) tree[i] = new ArrayList<>();
        for (int i = 0; i < N - 1; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            int w = Integer.parseInt(st.nextToken());
            tree[u].add(new int[]{v, w});
            tree[v].add(new int[]{u, w});
        }

        depth = new int[N + 1];
        parent = new int[N + 1][LOG];
        distFromRoot = new long[N + 1];
        dfs(1, 0, 0);

        int Q = Integer.parseInt(br.readLine());
        StringBuilder sb = new StringBuilder();
        for (int q = 0; q < Q; q++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            int c = Integer.parseInt(st.nextToken());
            long ans = solve(a, b, c);
            sb.append(ans).append("\n");
        }
        System.out.print(sb);
    }

    static void dfs(int node, int par, int d) {
        depth[node] = d;
        parent[node][0] = par;
        for (int i = 1; i < LOG; i++) {
            parent[node][i] = parent[parent[node][i - 1]][i - 1];
        }
        for (int[] edge : tree[node]) {
            int next = edge[0];
            int w = edge[1];
            if (next == par) continue;
            distFromRoot[next] = distFromRoot[node] + w;
            dfs(next, node, d + 1);
        }
    }

    static int lca(int u, int v) {
        if (depth[u] < depth[v]) {
            int tmp = u; u = v; v = tmp;
        }
        int diff = depth[u] - depth[v];
        for (int i = 0; i < LOG; i++) {
            if ((diff & (1 << i)) != 0) {
                u = parent[u][i];
            }
        }
        if (u == v) return u;
        for (int i = LOG - 1; i >= 0; i--) {
            if (parent[u][i] != parent[v][i]) {
                u = parent[u][i];
                v = parent[v][i];
            }
        }
        return parent[u][0];
    }

    static long dist(int u, int v) {
        int l = lca(u, v);
        return distFromRoot[u] + distFromRoot[v] - 2 * distFromRoot[l];
    }

    static long solve(int a, int b, int c) {
        // candidate meeting points: LCA of each pair
        int ab = lca(a, b);
        int bc = lca(b, c);
        int ca = lca(c, a);

        long d1 = Math.max(dist(a, ab), Math.max(dist(b, ab), dist(c, ab)));
        long d2 = Math.max(dist(a, bc), Math.max(dist(b, bc), dist(c, bc)));
        long d3 = Math.max(dist(a, ca), Math.max(dist(b, ca), dist(c, ca)));

        return Math.min(d1, Math.min(d2, d3));
    }
}

import java.io.*;
