public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int to;
        long w;
        Edge(int to, long w) {
            this.to = to;
            this.w = w;
        }
    }

    static int N, LOG;
    static ArrayList<Edge>[] g;
    static int[][] up;
    static int[] depth;
    static long[] dist;

    static void dfs(int root) {
        int[] stack = new int[N];
        int[] parent = new int[N];
        int top = 0;
        stack[top++] = root;
        parent[root] = root;
        depth[root] = 0;
        dist[root] = 0;

        while (top > 0) {
            int v = stack[--top];
            up[0][v] = parent[v];
            for (Edge e : g[v]) {
                if (e.to == parent[v]) continue;
                parent[e.to] = v;
                depth[e.to] = depth[v] + 1;
                dist[e.to] = dist[v] + e.w;
                stack[top++] = e.to;
            }
        }
    }

    static int lca(int a, int b) {
        if (depth[a] < depth[b]) {
            int t = a; a = b; b = t;
        }
        int diff = depth[a] - depth[b];
        for (int k = 0; k < LOG; k++) {
            if (((diff >> k) & 1) != 0) a = up[k][a];
        }
        if (a == b) return a;
        for (int k = LOG - 1; k >= 0; k--) {
            if (up[k][a] != up[k][b]) {
                a = up[k][a];
                b = up[k][b];
            }
        }
        return up[0][a];
    }

    static long distance(int a, int b) {
        int c = lca(a, b);
        return dist[a] + dist[b] - 2L * dist[c];
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < N - 1; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            long c = fs.nextLong();
            g[a].add(new Edge(b, c));
            g[b].add(new Edge(a, c));
        }

        LOG = 1;
        while ((1 << LOG) <= N) LOG++;
        up = new int[LOG][N];
        depth = new int[N];
        dist = new long[N];

        dfs(0);

        for (int k = 1; k < LOG; k++) {
            for (int v = 0; v < N; v++) {
                up[k][v] = up[k - 1][up[k - 1][v]];
            }
        }

        int Q = fs.nextInt();
        StringBuilder sb = new StringBuilder();

        for (int qi = 0; qi < Q; qi++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            int c = fs.nextInt() - 1;

            long dab = distance(a, b);
            long dbc = distance(b, c);
            long dca = distance(c, a);

            long ans = (dab + dbc + dca) / 2L;
            long maxPair = Math.max(dab, Math.max(dbc, dca));
            ans -= maxPair / 2L;

            sb.append(ans).append('\n');
        }

        System.out.print(sb.toString());
    }
}

