    for (auto &[v, w] : adj[u]) {
        if (v == p) continue;
        dfs(v, u, d + w);
    }
}

int lca(int u, int v) {
    if (depth[u] < depth[v]) swap(u, v);
    int diff = depth[u] - depth[v];
    for (int i = 0; i < LOG; ++i) {
        if (diff & (1 << i)) {
            u = up[u][i];
        }
    }
    if (u == v) return u;
    for (int i = LOG-1; i >= 0; --i) {
        if (up[u][i] != up[v][i]) {
            u = up[u][i];
            v = up[v][i];
        }
    }
    return up[u][0];
}

long long dist(int u, int v) {
    int w = lca(u, v);
    return distFromRoot[u] + distFromRoot[v] - 2 * distFromRoot[w];
}

