#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct LCA {
    int n, LOG;
    vector<vector<pair<int,int>>> g;
    vector<int> depth;
    vector<ll> dist;
    vector<vector<int>> up;

    LCA(int n): n(n) {
        LOG = 1;
        while ((1 << LOG) <= n) LOG++;
        g.assign(n + 1, {});
        depth.assign(n + 1, 0);
        dist.assign(n + 1, 0);
        up.assign(LOG, vector<int>(n + 1, 0));
    }

    void addEdge(int u, int v, int w) {
        g[u].push_back({v, w});
        g[v].push_back({u, w});
    }

    void build(int root = 1) {
        queue<int> q;
        vector<int> vis(n + 1, 0);
        vis[root] = 1;
        up[0][root] = 0;
        depth[root] = 0;
        dist[root] = 0;
        q.push(root);

        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto [v, w] : g[u]) {
                if (vis[v]) continue;
                vis[v] = 1;
                depth[v] = depth[u] + 1;
                dist[v] = dist[u] + w;
                up[0][v] = u;
                q.push(v);
            }
        }

        for (int k = 1; k < LOG; k++) {
            for (int v = 1; v <= n; v++) {
                int p = up[k - 1][v];
                up[k][v] = p ? up[k - 1][p] : 0;
            }
        }
    }

    int lca(int a, int b) const {
        if (depth[a] < depth[b]) swap(a, b);
        int diff = depth[a] - depth[b];
        for (int k = 0; k < LOG; k++) {
            if (diff & (1 << k)) a = up[k][a];
        }
        if (a == b) return a;
        for (int k = LOG - 1; k >= 0; k--) {
            if (up[k][a] != up[k][b]) {
                a = up[k][a];
                b = up[k][b];
            }
        }
        return up[0][a];
    }

    ll distance(int a, int b) const {
        int c = lca(a, b);
        return dist[a] + dist[b] - 2LL * dist[c];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    LCA solver(N);
    for (int i = 0; i < N - 1; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        solver.addEdge(u, v, w);
    }
    solver.build(1);

    int Q;
    cin >> Q;
    while (Q--) {
        int a, b, c;
        cin >> a >> b >> c;

        ll dab = solver.distance(a, b);
        ll dbc = solver.distance(b, c);
        ll dca = solver.distance(c, a);

        // Minimum possible maximum distance to a meeting point
        // equals half of the diameter of the three terminals, rounded up in tree metric.
        ll diameter = max({dab, dbc, dca});
        cout << (diameter + 1) / 2 << '\n';
    }

    return 0;
}
